// Normalise a submission from either trigger, validate it and run the spam checks.
// Rules (free-mail domains, honeypot, link limit, blocked phrases) live in config/icp.json.
const crypto = require('crypto');
const icp = $input.first().json.icp;
const sub = $('When called by an intake workflow').first().json;
const f = sub.fields || {};

const clean = (v, max = 200) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const name = clean(f.name);
const email = clean(f.email, 254).toLowerCase();
const message = String(f.message ?? '').trim().slice(0, 5000);
const role = clean(f.role);
const budget = clean(f.budget_range ?? f.budget, 60);
let company = clean(f.company);

const errors = [];
if (!name) errors.push('name is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.push('email is not valid');
if (!message) errors.push('message is required');

const emailDomain = email.includes('@') ? email.split('@').pop() : '';
const personal = icp.free_mail_domains.includes(emailDomain);

// Plain string parsing: the URL global is not available inside n8n task runners.
let websiteUrl = '';
let websiteDomain = '';
const host = clean(f.website, 500).toLowerCase()
  .replace(/^[a-z][a-z0-9+.-]*:\/\//, '')  // scheme
  .replace(/^[^@/]*@/, '')                  // user:pass@
  .split(/[\/?#:]/)[0]                      // path, query, port
  .replace(/^www\./, '');
if (/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(host)) {
  websiteDomain = host;
  websiteUrl = `https://${host}`;
}
if (!websiteDomain && emailDomain && !personal) {
  websiteDomain = emailDomain;
  websiteUrl = `https://${emailDomain}`;
}
if (!company && websiteDomain) company = websiteDomain.split('.')[0];

const spam = [];
const rules = icp.spam;
if (clean(f[rules.honeypot_field])) spam.push('honeypot field filled');
const links = (message.match(/(https?:\/\/|www\.)/gi) || []).length;
if (links > rules.max_links_in_message) spam.push(`${links} links in message`);
const lower = message.toLowerCase();
for (const phrase of rules.blocked_phrases) if (lower.includes(phrase)) spam.push(`blocked phrase: ${phrase}`);

const leadHash = crypto.createHash('sha256').update(`${email}\n${message}`).digest('hex');
const lead = {
  lead_id: `ld_${crypto.randomBytes(6).toString('hex')}`,
  lead_hash: leadHash,
  source: sub.source,
  received_at: new Date().toISOString(),
  name, email, email_domain: emailDomain, personal_email: personal,
  company, website_url: websiteUrl, website_domain: websiteDomain,
  role, budget_range: budget, message,
};

const check = errors.length ? 'invalid' : spam.length ? 'spam' : 'ok';
const response = check === 'invalid'
  ? { code: 422, body: { status: 'invalid', errors } }
  : check === 'spam'
    ? { code: 200, body: { status: 'rejected_spam' } }
    : null;
return [{ json: { check, errors, spam_reasons: spam, lead, response } }];

// The claim query returns the lead_id only when the lead is new.
const checked = $('Validate + normalise').first().json;
const claimed = $input.first().json.lead_id === checked.lead.lead_id;
return [{ json: {
  ...checked,
  check: claimed ? 'accepted' : 'duplicate',
  response: claimed
    ? { code: 202, body: { status: 'accepted', lead_id: checked.lead.lead_id } }
    : { code: 200, body: { status: 'duplicate_ignored' } },
} }];
